mapper.select:
select count(*)
from ujcms_article_related
where article_id_ = #{articleId,jdbcType=BIGINT}
  and related_id_ = #{relatedId,jdbcType=BIGINT}

select max(order_)
from ujcms_article_related
where article_id_ = #{articleId,jdbcType=BIGINT}

select
from ujcms_article t join ujcms_article_related ar on ar.related_id_ = t.id_ where ar.article_id_ = #{articleId,jdbcType=BIGINT}
order by ar.order_ asc, t.id_ desc

select
from ujcms_article t join ujcms_article_related ar on ar.article_id_ = t.id_ where ar.related_id_ = #{articleId,jdbcType=BIGINT}
order by t.publish_date_ desc, t.id_ desc

mapper.delete:
delete from ujcms_article_related
where article_id_ = #{articleId,jdbcType=BIGINT}
  and related_id_ = #{relatedId,jdbcType=BIGINT}

delete from ujcms_article_related
where article_id_ = #{articleId,jdbcType=BIGINT}
   or related_id_ = #{articleId,jdbcType=BIGINT}
